const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function safeProductUrl(value){try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)&&!url.username&&!url.password&&url.href.length<=2048?url.href:null;}catch{return null;}}
function productName(record){const url=safeProductUrl(record.productUrl);return url?`<a class="product-link" href="${escapeHTML(url)}" data-product-record="${escapeHTML(record.id)}" title="Abrir publicación del producto">${escapeHTML(record.product)}</a>`:escapeHTML(record.product);}
function pastedProductLink(clipboard){
 const html=clipboard.getData('text/html');if(!html)return null;
 const doc=new DOMParser().parseFromString(html,'text/html');
 const nodes=[...doc.querySelectorAll('a[href], [data-sheets-hyperlink]')];
 const links=nodes.map(el=>({url:safeProductUrl(el.getAttribute('href')||el.getAttribute('data-sheets-hyperlink')),name:el.textContent.trim()})).filter(x=>x.url&&x.name);
 const unique=[...new Map(links.map(x=>[x.url+'\n'+x.name,x])).values()];if(unique.length!==1)return null;
 const link=unique[0],plain=clipboard.getData('text/plain').trim();
 // A pasted range must not attach the first cell's URL to unrelated cells.
 const normal=s=>s.replace(/\s+/g,' ').trim();if(plain&&normal(plain)!==normal(link.name))return null;
 return link.name.length<=300?link:null;
}
document.addEventListener('input',e=>{if(e.target.matches('#record-form [name="product"]')){e.target.form.elements.productUrl.value='';document.getElementById('product-link-status').hidden=true;}});
document.addEventListener('paste',e=>{
 if(!e.target.matches('#record-form [name="product"]')||!e.clipboardData)return;
 const input=e.target,link=pastedProductLink(e.clipboardData);
 if(!link||input.value&&(input.selectionStart!==0||input.selectionEnd!==input.value.length))return;
 e.preventDefault();input.value=link.name;input.dispatchEvent(new Event('input',{bubbles:true}));
 input.form.elements.productUrl.value=link.url;document.getElementById('product-link-status').hidden=false;
 input.setSelectionRange(input.value.length,input.value.length);
});
document.addEventListener('click',async e=>{
 const link=e.target.closest('[data-product-record]');if(!link)return;e.preventDefault();
 try{await window.cxDesktop.openProductLink(link.dataset.productRecord);}catch(err){const status=document.createElement('p');status.className='form-error';status.setAttribute('role','alert');status.textContent=authError(err);link.after(status);}
});
const money = cents => (cents/100).toLocaleString('es-MX',{minimumFractionDigits:2,maximumFractionDigits:2});
const cents = value => Math.round(Number(value)*100);
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
const claimReasons = {
 [claimComponents.unifiedReason]:[],
 'El comprador se arrepintió':['No le gustó el estado estético','No le gustó el tamaño de pantalla','No le gustó la distribución del teclado','Rendimiento menor al esperado','No compatible con sus programas','Prefiere equipo nuevo','Estética','Ya no necesita el producto','Compra realizada por error','Encontró una mejor opción o precio','No cumplió sus expectativas','No se adapta a sus necesidades','Tamaño o peso no adecuado','Prefiere otro modelo','Tiempo de entrega no adecuado','Cambio de presupuesto','Otro'],
 'El producto es diferente':['Generación de procesador diferente','Tipo de RAM diferente','Pantalla no táctil','Frecuencia de pantalla diferente','Capacidad de batería diferente','Cargador distinto al anunciado','Accesorios no corresponden','Estado de batería diferente al anunciado','Conectividad anunciada faltante','Edición de Windows diferente','Estética','Menor capacidad de RAM','Menor capacidad de SSD o disco duro','Tipo de almacenamiento diferente','Menor resolución de pantalla','Tamaño de pantalla diferente','Procesador diferente','Tarjeta gráfica diferente','Teclado con idioma o distribución diferente','Teclado sin retroiluminación anunciada','Modelo o marca diferente','Color diferente','Sistema operativo diferente','Puertos o conectividad diferentes','Condición estética diferente a la anunciada','Accesorios diferentes o faltantes','Otro']
};
function refreshFaultFields(reason,component,specific,reset,componentChanged=false){
 const date=document.getElementById('record-form')?.elements.date.value,reported=claimComponents.isReported(reason,date),grouped=claimComponents.isComponentReason(reason);component.closest('label').firstChild.textContent=reported?'Problema reportado por el cliente *':'Componente dañado o fallando *';
 component.closest('label').hidden=!grouped;component.disabled=!grouped;component.required=grouped;
 if(reset){component.innerHTML='<option value="">'+(reported?'Selecciona un problema reportado':'Selecciona un componente')+'</option>'+(reported?claimComponents.reportedCategories():claimComponents.components(reason)).map(v=>`<option>${escapeHTML(v)}</option>`).join('');}
 if(reset||componentChanged){specific.innerHTML='<option value="">'+(grouped?'Selecciona una falla específica':'Selecciona un motivo específico')+'</option>'+(grouped?(reported?claimComponents.reportedSpecifics(component.value):claimComponents.specifics(reason,component.value)):(claimReasons[reason]||[])).map(v=>`<option>${escapeHTML(v)}</option>`).join('');}
 if(reset||componentChanged)specific.selectedIndex=-1;
 specific.disabled=!reason||(grouped&&!component.value);refreshSpecificChoices(specific,reset||componentChanged);
}
function updateDateClassification(){const form=document.getElementById('record-form');if(!form)return;const mode='reported';if(form.dataset.claimMode&&form.dataset.claimMode!==mode){updateClaimFields(true);for(const row of form.querySelectorAll('.fault-row'))updateFault(row,true);}form.dataset.claimMode=mode;}
const responsibleAreas=['Empaque - Logística','Ecommerce - Marketing','Cliente','Acondicionamiento','Paquetería'];
function updateResponsibleArea(){const form=document.getElementById('record-form');if(!form)return;const required=true,select=form.elements.responsibleArea;select.disabled=false;select.required=required;select.closest('label').hidden=false;select.closest('label').firstChild.textContent=required?'Área responsable *':'Área responsable (opcional)';}
function refreshSpecificChoices(select,reset){let box=select.nextElementSibling;if(!box||!box.classList.contains('specific-choices')){box=document.createElement('div');box.className='specific-choices';select.after(box);reset=true;}if(reset){box.innerHTML=[...select.options].filter(o=>o.value).map(o=>`<label><input type="checkbox" data-specific-choice value="${escapeHTML(o.value)}"><span>${escapeHTML(o.text)}</span></label>`).join('')||'<p>Selecciona primero el motivo y el componente, cuando corresponda.</p>';}
 for(const check of box.querySelectorAll('input')){check.disabled=select.disabled;check.checked=[...select.selectedOptions].some(o=>o.value===check.value);}
}
function selectedSpecifics(select,other){return [...select.selectedOptions].filter(o=>o.value).map(o=>o.value==='Otro'?'Otro: '+other:o.value);}
function updateClaimFields(reset=false,componentChanged=false){
 const form=document.getElementById('record-form');if(!form)return;
 const reason=form.elements.reason,specific=form.elements.specificReason;
 refreshFaultFields(reason.value,form.elements.component,specific,reset,componentChanged);
 if(reset||componentChanged)form.elements.otherReason.value='';
 const other=[...specific.selectedOptions].some(o=>o.value==='Otro');document.getElementById('other-reason-field').hidden=!other;form.elements.otherReason.disabled=!other;form.elements.otherReason.required=other;
}
let faultSequence=0;
function addFault(){
 const list=document.getElementById('fault-list');if(!list)return;
 const id=++faultSequence;
 const row=document.createElement('div');row.className='fault-row';row.dataset.fault=String(id);
 row.innerHTML=`<label>Motivo de la falla *<select class="fault-category" required><option value="">Selecciona un motivo</option>${Object.keys(claimReasons).map(v=>`<option>${escapeHTML(v)}</option>`).join('')}</select></label><label hidden>Componente dañado o fallando *<select class="fault-component" disabled><option value="">Selecciona un componente</option></select></label><div class="specific-field"><span class="field-label">Falla específica *</span><select class="fault-specific" multiple hidden disabled><option value="">Selecciona primero un motivo</option></select></div><button type="button" class="secondary-button remove-fault" aria-label="Quitar falla adicional ${id}">Quitar</button><label class="fault-other" hidden>Describe la falla *<textarea disabled maxlength="2000" rows="2"></textarea></label>`;
 list.append(row);row.querySelector('select').focus();
}
function updateFault(row,reset,componentChanged=false){
 const category=row.querySelector('.fault-category'),specific=row.querySelector('.fault-specific'),other=row.querySelector('.fault-other'),text=other.querySelector('textarea');
 refreshFaultFields(category.value,row.querySelector('.fault-component'),specific,reset,componentChanged);
 if(reset||componentChanged)text.value='';
 other.hidden=![...specific.selectedOptions].some(o=>o.value==='Otro');text.disabled=other.hidden;text.required=!other.hidden;
}
function registrationRoute(type,received){return received&&type===0?{...routes[type],resolution:'Reparación',module:'reparacion',index:0,destination:'Reparación / Expedientes • Devoluciones'}:routes[type];}
function updateRegistrationDestination(){const form=document.getElementById('record-form');if(!form?.elements.receivedOnRegistration)return;const checked=form.elements.receivedOnRegistration.checked,outcomeRequired=checked&&types.indexOf(recordType)===0;form.elements.receivedOutcome.disabled=!outcomeRequired;form.elements.receivedOutcome.required=outcomeRequired;document.getElementById('received-outcome-field').hidden=!outcomeRequired;const route=registrationRoute(types.indexOf(recordType),checked);form.elements.resolution.value=route.resolution;form.elements.serial.required=checked;document.getElementById('registration-serial-label').textContent='Número de serie / SN'+(checked?' *':'');form.elements.serial.placeholder=checked?'Escanea o escribe el número de serie':'Opcional';document.getElementById('registration-destination').textContent='Destino: '+route.destination;document.getElementById('form-route-destination').textContent=route.destination;}
