 const record={receivedOutcome:receivedOnRegistration&&type===0?data.get('receivedOutcome'):null,responsibleArea:data.get('responsibleArea')||null,specificReasons:selectedSpecifics(form.elements.specificReason,data.get('otherReason')),receivedOnRegistration,customerReason:data.get('customerReason'),additionalFaults,id:crypto.randomUUID(),expedientNumber:Math.max(records.length,...records.map(r=>r.expedientNumber||0))+1,type,date:data.get('date'),order:data.get('order'),product:data.get('product'),productUrl:data.get('productUrl')||null,serial:data.get('serial').trim(),quantity:Number(data.get('quantity')),price:cents(data.get('price')),contact:data.get('contact'),reason:data.get('reason'),component:data.get('component')||null,specificReason:selectedSpecifics(form.elements.specificReason,data.get('otherReason')).join(' · '),resolution:route.resolution,total:type===3?refund:total,orderTotal:total,module:route.module,index:route.index,tag:route.tag||null,refund,refundMode:type===3?data.get('refundMode'):null,percentage:type===3&&data.get('refundMode')==='percentage'?Number(data.get('percentage')):null};
