const search=document.getElementById('global-search'),results=document.getElementById('search-results');
const normal = s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
let globalSearchRequest=0,globalSearchTimer;
function closeGlobalSearch(){globalSearchRequest++;clearTimeout(globalSearchTimer);results.hidden=true;search.setAttribute('aria-expanded','false');}
async function searchModules(){
 clearTimeout(globalSearchTimer);const query=search.value.trim(),request=++globalSearchRequest;
 if(!query){results.hidden=true;search.setAttribute('aria-expanded','false');return;}
 const q=normal(query),tokens=q.split(/\s+/),matches=value=>tokens.every(t=>normal(String(value||'')).includes(t));
 const entries=modules.filter(m=>can(m.id)).flatMap(m=>[{id:m.id,index:0,name:m.name,icon:m.icon},...m.items.filter((it,i)=>m.id!=='configuracion'||i!==1||isAdmin()).map(it=>({id:m.id,index:m.items.indexOf(it),name:`${m.name} / ${it[0]}`,icon:it[1]}))]).filter(e=>matches(e.name));
 results.hidden=false;search.setAttribute('aria-expanded','true');results.innerHTML='<p role="status">Buscando…</p>';
 try{
  const rows=await desktop.listRecords();if(request!==globalSearchRequest||search.value.trim()!==query||!currentUser)return;
  const found=rows.filter(r=>matches([recordNumber(r),'EXP-'+r.expedientNumber,r.order,r.serial,r.barcode,r.product].filter(Boolean).join(' '))).sort((a,b)=>{const exact=r=>[recordNumber(r),'EXP-'+r.expedientNumber,r.order,r.serial,r.barcode].some(v=>normal(String(v||''))===q);return Number(exact(b))-Number(exact(a));});
  results.innerHTML=(found.length?`<div class="search-group-title">Expedientes · ${found.length} resultados</div>${found.slice(0,30).map(r=>`<button class="global-record-result" data-search-record="${escapeHTML(r.id)}">${icon('monitor')}<span><strong>${recordNumber(r)} · Pedido ${escapeHTML(r.order)}</strong><span>${escapeHTML(r.product)}</span><small>${escapeHTML((r.serial||r.barcode)?'SN / Barcode: '+(r.serial||r.barcode):'Sin número de serie')} · ${escapeHTML(r.location)}</small></span>${icon('chevron')}</button>`).join('')}${found.length>30?'<p>Se muestran los primeros 30. Escribe más datos para precisar la búsqueda.</p>':''}`:'')+(entries.length?`<div class="search-group-title">Módulos</div>${entries.map(e=>`<button data-search-module="${e.id}" data-index="${e.index}">${icon(e.icon)}${escapeHTML(e.name)}</button>`).join('')}`:'')||'<p role="status">No encontramos expedientes ni módulos con esos datos.</p>';
 }catch(err){if(request===globalSearchRequest)results.innerHTML=`<p role="alert">${escapeHTML(authError(err))}</p>`;}
}
