results.addEventListener('keydown',e=>{if(!['ArrowDown','ArrowUp','Home','End','Escape'].includes(e.key))return;e.preventDefault();if(e.key==='Escape'){closeGlobalSearch();search.focus();closeGlobalSearch();return;}const buttons=[...results.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);const next=e.key==='Home'?0:e.key==='End'?buttons.length-1:Math.min(buttons.length-1,Math.max(0,i+(e.key==='ArrowDown'?1:-1)));buttons[next]?.focus();});
const notify=document.getElementById('notifications'),np=document.getElementById('notification-panel');notify.innerHTML=icon('bell');notify.addEventListener('click',async()=>{await refreshNotifications();np.hidden=!np.hidden;notify.setAttribute('aria-expanded',String(!np.hidden));});
async function refreshNotifications(){if(!currentUser)return;try{const rows=isAdmin()?await desktop.listNotifications():[];const unread=rows.filter(n=>!n.read).length;notify.innerHTML=icon('bell')+(unread?`<span class="notification-badge">${unread}</span>`:'');notify.setAttribute('aria-label',unread?`Notificaciones: ${unread} sin leer`:'Notificaciones');np.innerHTML='<h3>Notificaciones</h3>'+(rows.length?rows.map(n=>`<button class="notification-item ${n.read?'':'unread'}" data-notification="${n.id}" data-record="${n.recordId}"><strong>EXP-${String(n.expedientNumber).padStart(3,'0')} · ${escapeHTML(n.result)}</strong><span>${escapeHTML(n.technician)} · Pedido ${escapeHTML(n.order)}</span><small>${escapeHTML(new Date(n.createdAt).toLocaleString('es-MX'))}</small></button>`).join(''):'<div class="notification-empty">Estás al día<small>No hay notificaciones por ahora.</small></div>');}catch(e){np.textContent=authError(e);}}
np.addEventListener('click',async e=>{const b=e.target.closest('[data-notification]');if(!b)return;await desktop.readNotification(b.dataset.notification);records=await desktop.listRecords();const r=records.find(r=>r.id===b.dataset.record);if(r){navigate(r.module,r.index);openRecord=r;detailTab='repair';render();}await refreshNotifications();np.hidden=true;});
setInterval(()=>{if(isAdmin())refreshNotifications();},20000);
document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))closeGlobalSearch();if(!e.target.closest('#notification-panel')&&!e.target.closest('#notifications')){np.hidden=true;notify.setAttribute('aria-expanded','false');}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search.focus();}if(e.key==='Escape'){closeGlobalSearch();np.hidden=true;search.setAttribute('aria-expanded','false');notify.setAttribute('aria-expanded','false');}});
if(!navigator.platform.includes('Mac'))document.getElementById('shortcut').textContent='Ctrl K';
startAuth();

content.addEventListener('invalid',e=>{if(e.target.closest('#record-form')){const section=e.target.closest('details');if(section)section.open=true;const error=document.getElementById('form-error');if(error){error.hidden=false;error.textContent='Completa el campo señalado antes de continuar.';}}},true);
